class Feedback{submit(){const n=$("#gameForm");if(this.validateContent(n)){let t=new FormData(n[0]);n.find("#submitBtn").prop("disabled",!0);$.ajax({method:"POST",url:"/feedback/AddFeedback",data:t,processData:!1,contentType:!1}).done(function(t){t.success?(n.find("#failedMsg").hide(),parent.postMessage({showSuccess:!0},"*"),feedback.showSuccessModal(""),n.find("#submitBtn").prop("disabled",!1)):(n.find("#failedMsg").show(),n.find("#failedMsgContent").html(t.message),n.find("#submitBtn").prop("disabled",!1))})}}validateContent(n){var t=$("#descText").val();return t===""?(n.find("#failedMsg").show(),n.find("#failedMsgContent").html("(The description can't be empty)"),!1):(n.find("#failedMsg").hide(),!0)}showSuccessModal(){const n=$("#successModal");name||(name="");n.modal("show")}closeSuccessModal(){console.log("close");parent.postMessage({closeSuccess:!0},"*")}openSelectFile(){$(".to-add-input").trigger("click")}onFileInputChanged(n){var i=n.files[0],t;$(n).parent().parent().find(".to-add-name").html(i.name);$(n).removeClass("to-add-input");$(n).parent().parent().removeAttr("hidden");$('<li class="added-image" hidden><div><img class="attach-img"/><img class="remove-img" onclick="feedback.removeAttachment(this)"/><br/><span class="to-add-name"><\/span><input type="file" accept="image/x-png,image/gif,image/jpeg" class="to-add-input" name="Feedback.Files" hidden onchange="feedback.onFileInputChanged(this)"><\/div><\/li>').insertBefore(".to-add-image");t=$(".image-container ul");t.animate({scrollLeft:t[0].scrollWidth});feedback.updateAttachmentCount()}onDescKeyUp(){console.log("upp");feedback.validateContent($("#gameForm"))}removeAttachment(n){$(n).parent().parent().remove();feedback.updateAttachmentCount()}updateAttachmentCount(){$(".attachment-count").html($(".added-image").length-1)}}var feedback=new Feedback;$("#successModal").on("hidden.bs.modal",function(){feedback.closeSuccessModal()});